use std::fs

fn emit(content: string, number: bool, counter: int) -> int {
    if !number {
        print("${content}")
        return counter
    }
    if content.len() == 0 {
        return counter
    }
    let mut c = counter
    let mut parts: Vec<string> = []
    for p in content.split("\n") {
        parts.push(p.to_string())
    }
    let n: int = parts.len() as int
    let mut i: int = 0
    for p in parts {
        i += 1
        if i == n && p.len() == 0 {
            break
        }
        c += 1
        println("${c:>6}\t${p}")
    }
    c
}

fn main() {
    let mut number = false
    let mut names: Vec<string> = []
    for a in std::env::args().skip(1) {
        if a == "-n" {
            number = true
        } else {
            names.push(a)
        }
    }
    let mut counter: int = 0
    let mut status: int = 0
    if names.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for name in names {
            match fs::read_to_string(name) {
                Ok(t) => { counter = emit(t, number, counter) }
                Err(_) => {
                    println("cat: ${name}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        std::process::exit(1)
    }
}

